/// <summary>
/// main method
/// </summary>
/// <param name = "_args">Args</param>
public static void main(Args _args)
{
    AVACRLCreditLimitController controller;

    controller = new AVACRLCreditLimitController(classStr(AVACRLCreditLimitService),
                                       methodStr(AVACRLCreditLimitService, startOperation),
                                       SysOperationExecutionMode::Synchronous);

    controller.startOperation();
}

/// <summary>
/// default description of class
/// </summary>
/// <returns>ClassDescription</returns>
protected ClassDescription defaultCaption()
{
    return "@NDX:NXACRLCreditLimitExceed";
}
